from pathlib import Path
p=Path('a-ware/index.html')
s=p.read_text(encoding='utf-8')
s=s.replace('A-WARE v0.24.1 · IDLE BASE','A-WARE v0.24.2 · OBJECT DISCOVERY')
s=s.replace('.controlTitle{font-size:9px;letter-spacing:.15em;color:#70f5ff;margin-bottom:5px}', '.controlTitle{font-size:9px;letter-spacing:.15em;color:#70f5ff;margin-bottom:7px}.knownItem{display:flex;align-items:center;gap:7px;padding:5px 0;border-bottom:1px solid #5ff1;font-size:9px}.knownIcon{width:18px;text-align:center;font-size:14px;color:#8ef7ff}.knownItem.controlled{color:#dfffff;text-shadow:0 0 7px #5ff6}.revealToast{position:fixed;left:50%;top:18%;transform:translate(-50%,-10px);padding:10px 16px;border:1px solid #72f7ff;background:#03161ddd;color:#bfffff;font-size:11px;letter-spacing:.16em;opacity:0;pointer-events:none;transition:.22s;z-index:20;box-shadow:0 0 30px #00eaff33}.revealToast.on{opacity:1;transform:translate(-50%,0)}.hoverCard{position:fixed;display:none;z-index:30;min-width:150px;max-width:220px;padding:8px;border:1px solid #65f5ff88;background:#031319ee;box-shadow:0 0 22px #00ddff30;backdrop-filter:blur(8px);pointer-events:auto}.hoverCard.on{display:block}.hoverName{font-size:10px;letter-spacing:.1em;color:#bfffff;margin-bottom:6px}.hoverState{font-size:8px;opacity:.55;margin-bottom:5px}.hoverActions{display:flex;flex-wrap:wrap;gap:4px}.hoverActions button{padding:5px 7px;font-size:9px;width:auto}')
s=s.replace('<canvas id="scene"></canvas><div class="scan"></div>', '<canvas id="scene"></canvas><div id="revealToast" class="revealToast"></div><div id="hoverCard" class="hoverCard"></div><div class="scan"></div>',1)
s=s.replace('<div class="controlPanel"><div class="controlTitle">CONTROL DISPONIBLE</div><div id="controlList"></div><div id="objective" class="objective">OBSERVÁ. ESCUCHÁ. CONSEGUÍ ACCESO.</div></div>', '<div class="controlPanel"><div class="controlTitle">ELEMENTOS REVELADOS</div><div id="knownList"></div><div id="controlList" style="display:none"></div><div id="objective" class="objective">OBSERVÁ. ESCUCHÁ. CONSEGUÍ ACCESO.</div></div>',1)
p.write_text(s,encoding='utf-8')